import { Inject, Injectable, Scope } from '@nestjs/common'
import { REQUEST } from '@nestjs/core'
import type { Request } from 'express'
import { randomUUID } from 'node:crypto'

@Injectable({ scope: Scope.REQUEST })
export class RequestContext {
  readonly requestId: string
  readonly tenantId: string

  constructor(@Inject(REQUEST) req: Request) {
    this.requestId = req.header('x-request-id') ?? randomUUID()
    this.tenantId = req.header('x-tenant-id') ?? 'public'
  }
}

import { Injectable } from '@nestjs/common'
import { Database } from '../database'
import { RequestContext } from '../request-context'

@Injectable()
export class OrdersRepository {
  constructor(
    private readonly db: Database,
    private readonly ctx: RequestContext,
  ) {}

  findAll() {
    return this.db.query('select * from orders where tenant_id = $1', [this.ctx.tenantId])
  }
}

