import { Module } from '@nestjs/common'
import type { Request } from 'express'
import { ClsModule } from 'nestjs-cls'
import { OrdersModule } from './orders/orders.module'

@Module({
  imports: [
    ClsModule.forRoot({
      global: true,
      middleware: {
        mount: true,
        setup: (cls, req: Request) => {
          cls.set('tenantId', req.header('x-tenant-id') ?? 'public')
        },
      },
    }),
    OrdersModule,
  ],
})
export class AppModule {}

import { Injectable } from '@nestjs/common'
import { ClsService } from 'nestjs-cls'
import { Database } from '../database'

@Injectable()
export class OrdersRepository {
  private readonly tenantId: string

  constructor(
    private readonly db: Database,
    cls: ClsService,
  ) {
    this.tenantId = cls.get('tenantId')
  }

  findAll() {
    return this.db.query('select * from orders where tenant_id = $1', [this.tenantId])
  }
}

import { Injectable } from '@nestjs/common'
import { ClsService } from 'nestjs-cls'
import { Database } from '../database'

@Injectable()
export class OrdersRepository {
  constructor(
    private readonly db: Database,
    private readonly cls: ClsService,
  ) {}

  findAll() {
    const tenantId = this.cls.get<string>('tenantId')
    return this.db.query('select * from orders where tenant_id = $1', [tenantId])
  }
}
